SELECT COUNT(*) AS total_count,SUM(CASE WHEN outcome IS NOT NULL THEN 1 ELSE 0 END) AS processed_count,SUM(CASE WHEN outcome='ADDED' THEN 1 ELSE 0 END) AS added_count,SUM(CASE WHEN outcome='UPDATED' THEN 1 ELSE 0 END) AS updated_count,SUM(CASE WHEN outcome='PRESERVED' THEN 1 ELSE 0 END) AS preserved_count,SUM(CASE WHEN outcome='UNCHANGED' THEN 1 ELSE 0 END) AS unchanged_count,SUM(CASE WHEN verification IS NOT NULL THEN 1 ELSE 0 END) AS verified_count,SUM(CASE WHEN verification='PRESENT' THEN 1 ELSE 0 END) AS present_count,SUM(CASE WHEN verification='MISSING' THEN 1 ELSE 0 END) AS missing_count,SUM(CASE WHEN verification='MISMATCH' THEN 1 ELSE 0 END) AS mismatch_count,SUM(CASE WHEN verification='UNREACHABLE' THEN 1 ELSE 0 END) AS unreachable_count FROM media_import_entry WHERE job_id=@{id}
